//! Deterministic protocol-state simulation for Worldgen P10 F01-F04.
use std::collections::{BTreeMap, BTreeSet};
use bioprism_foundation::{PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.protocol-simulation-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ProtocolStep{pub step_id:String,pub action:String,pub resource_need_milli:u32,pub risk_milli:u32,pub duration_milli:u32,pub compensatable:bool,pub evidence_state:String,pub evidence_digest:ContentHash,pub provenance_digest:ContentHash,pub artifact_digest:ContentHash,pub replay_identity:ContentHash,pub permitted:bool,pub raw_data_local:bool,pub negative_result:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ProtocolDraft{pub request_id:String,pub protocol_id:String,pub purpose:String,pub semantic_profile:String,pub required_step_order:Vec<String>,pub step_order:Vec<String>,pub steps:Vec<ProtocolStep>,pub replay_identity:ContentHash,pub max_resource_milli:u32,pub max_risk_milli:u32,pub max_duration_milli:u32,pub policy_allow:bool,pub protected_closure:bool,pub federation_approved:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ProtocolSimulationReport{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub protocol_id:String,pub purpose:String,pub semantic_profile:String,pub disposition:String,pub required_step_order:Vec<String>,pub step_order:Vec<String>,pub admitted_step_order:Vec<String>,pub unresolved_step_order:Vec<String>,pub blocked_step_order:Vec<String>,pub omitted_step_order:Vec<String>,pub resource_need_milli_order:Vec<u32>,pub risk_milli_order:Vec<u32>,pub duration_milli_order:Vec<u32>,pub failure_order:Vec<String>,pub compensation_order:Vec<String>,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub contradiction:Vec<String>,pub negative_evidence:Vec<String>,pub replay_identity:ContentHash,pub simulation_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ProtocolSimulationError{#[error("invalid protocol simulation request: {0}")]Invalid(String),#[error("protocol simulation artifact failed: {0}")]Artifact(String),#[error("invalid protocol simulation report: {0}")]Report(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn s(mut v:Vec<String>)->Vec<String>{v.sort();v.dedup();v}
impl ProtocolSimulationReport{pub fn validate(&self)->Result<(),ProtocolSimulationError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.protocol_id.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||self.step_order.is_empty()||self.effect_receipts.is_empty()||![&self.replay_identity,&self.simulation_digest].into_iter().all(h){return Err(ProtocolSimulationError::Report("protocol identity, steps, locality, digests, or effects are incomplete".into()));}for v in [&self.required_step_order,&self.step_order,&self.admitted_step_order,&self.unresolved_step_order,&self.blocked_step_order,&self.omitted_step_order,&self.failure_order,&self.compensation_order,&self.omissions,&self.uncertainty,&self.contradiction,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(ProtocolSimulationError::Report("protocol vectors are not canonical".into()));}}let ids=self.step_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.admitted_step_order.iter().chain(&self.unresolved_step_order).chain(&self.blocked_step_order).chain(&self.omitted_step_order).cloned().collect::<Vec<_>>();if ids.len()!=self.step_order.len()||parts.len()!=ids.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=ids||self.resource_need_milli_order.len()!=ids.len()||self.risk_milli_order.len()!=ids.len()||self.duration_milli_order.len()!=ids.len(){return Err(ProtocolSimulationError::Report("protocol states or metric vectors do not partition".into()));}if self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.simulation_digest.as_str()){return Err(ProtocolSimulationError::Report("protocol artifact digest is inconsistent".into()));}if self.effect_receipts.iter().any(|e|e!="block:unsafe-release"&&!e.starts_with("simulate:worldgen-protocol:")){return Err(ProtocolSimulationError::Report("protocol effect is outside simulation gate".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["research program lead","preclinical neuroscientist","bioinformatician","imaging core scientist"],"behavior":format!("simulate preclinical protocol state machines for {scale}"),"value":"preflights resources, risks, failure branches, and compensations without executing protocols or touching instruments","input_schema":input_schema,"output_schema":"ProtocolSimulationReport1@1","effects":["simulate:worldgen-protocol","block:unsafe-release"],"permissions":["simulate:local-preclinical-protocol"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn simulate(request:&ProtocolDraft,feature_id:&str,version:&str,scale:&str,require_federation:bool)->Result<ProtocolSimulationReport,ProtocolSimulationError>{if request.request_id.trim().is_empty()||request.protocol_id.trim().is_empty()||request.purpose.trim().is_empty()||request.semantic_profile.trim().is_empty()||request.required_step_order.is_empty()||request.step_order.is_empty()||request.step_order!=s(request.step_order.clone())||request.required_step_order!=s(request.required_step_order.clone())||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||request.max_resource_milli>1000||request.max_risk_milli>1000||request.max_duration_milli>1000||!h(&request.replay_identity){return Err(ProtocolSimulationError::Invalid("protocol identity, ordering, thresholds, locality, boundary, or replay is invalid".into()));}if require_federation&&!request.federation_approved{return Err(ProtocolSimulationError::Invalid("protocol federation approval is required".into()));}let ids=request.step_order.iter().cloned().collect::<BTreeSet<_>>();let mut by_id=BTreeMap::new();for st in &request.steps{if !ids.contains(&st.step_id)||st.action.trim().is_empty()||st.boundary!=PRECLINICAL_BOUNDARY||!st.raw_data_local||st.replay_identity!=request.replay_identity||st.resource_need_milli>1000||st.risk_milli>1000||st.duration_milli>1000||!h(&st.evidence_digest)||!h(&st.provenance_digest)||!h(&st.artifact_digest)||!h(&st.replay_identity){return Err(ProtocolSimulationError::Invalid("protocol step identity, metrics, provenance, locality, replay, or boundary is invalid".into()));}if by_id.insert(st.step_id.clone(),st).is_some(){return Err(ProtocolSimulationError::Invalid("duplicate protocol step".into()));}}
let mut admitted=Vec::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut omitted=BTreeSet::new();let mut failures=BTreeSet::new();let mut compensation=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut contradiction=BTreeSet::new();let mut negative=BTreeSet::new();for id in &ids{match by_id.get(id){None=>{omitted.insert(id.clone());omissions.insert(format!("step:{}:missing",id));},Some(st)if !request.policy_allow||!request.protected_closure||!st.permitted=>{blocked.insert(id.clone());failures.insert(format!("step:{}:authorization-denied",id));omissions.insert(format!("step:{}:policy-or-permission-blocked",id));},Some(st)if st.negative_result=>{unresolved.insert(id.clone());negative.insert(format!("step:{}:negative-result-retained",id));if st.compensatable{compensation.insert(format!("step:{}:compensation-available",id));}},Some(st)if st.evidence_state=="contradicted"=>{unresolved.insert(id.clone());contradiction.insert(format!("step:{}:contradicted",id));failures.insert(format!("step:{}:contradiction",id));},Some(st)if st.evidence_state=="unknown"||st.evidence_state=="unmeasured"=>{unresolved.insert(id.clone());uncertainty.insert(format!("step:{}:{}",id,st.evidence_state));},Some(st)if st.resource_need_milli>request.max_resource_milli||st.risk_milli>request.max_risk_milli||st.duration_milli>request.max_duration_milli=>{unresolved.insert(id.clone());uncertainty.insert(format!("step:{}:resource-risk-duration-threshold",id));if st.compensatable{compensation.insert(format!("step:{}:compensation-available",id));}},Some(st)if st.evidence_state!="supported"&&st.evidence_state!="proven"=>{unresolved.insert(id.clone());uncertainty.insert(format!("step:{}:evidence-not-qualified",id));},Some(st)=>admitted.push(st)}}admitted.sort_by(|a,b|a.step_id.cmp(&b.step_id));let admitted_ids=admitted.iter().map(|x|x.step_id.clone()).collect::<BTreeSet<_>>();let authority=request.policy_allow&&request.protected_closure&&(!require_federation||request.federation_approved);let disposition=if !authority{"blocked"}else if admitted.is_empty(){"unknown"}else if admitted_ids.len()==ids.len()&&omissions.is_empty()&&unresolved.is_empty()&&blocked.is_empty(){"qualified"}else{"partial"};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("simulate:worldgen-protocol:{}",request.protocol_id)]};let resource=request.step_order.iter().map(|id|by_id.get(id).map(|x|x.resource_need_milli).unwrap_or(0)).collect::<Vec<_>>();let risk=request.step_order.iter().map(|id|by_id.get(id).map(|x|x.risk_milli).unwrap_or(0)).collect::<Vec<_>>();let duration=request.step_order.iter().map(|id|by_id.get(id).map(|x|x.duration_milli).unwrap_or(0)).collect::<Vec<_>>();let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.request_id,"protocol_id":request.protocol_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"scale":scale,"disposition":disposition,"required_step_order":request.required_step_order,"step_order":ids,"admitted_step_order":admitted_ids,"unresolved_step_order":unresolved,"blocked_step_order":blocked,"omitted_step_order":omitted,"resource_need_milli_order":resource,"risk_milli_order":risk,"duration_milli_order":duration,"failure_order":failures,"compensation_order":compensation,"omissions":omissions,"uncertainty":uncertainty,"contradiction":contradiction,"negative_evidence":negative,"replay_identity":request.replay_identity,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|ProtocolSimulationError::Artifact(e.to_string()))?;let r=ProtocolSimulationReport{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.request_id.clone(),protocol_id:request.protocol_id.clone(),purpose:request.purpose.clone(),semantic_profile:request.semantic_profile.clone(),disposition:disposition.into(),required_step_order:request.required_step_order.clone(),step_order:ids.iter().cloned().collect(),admitted_step_order:admitted_ids.iter().cloned().collect(),unresolved_step_order:unresolved.into_iter().collect(),blocked_step_order:blocked.into_iter().collect(),omitted_step_order:omitted.into_iter().collect(),resource_need_milli_order:resource,risk_milli_order:risk,duration_milli_order:duration,failure_order:failures.into_iter().collect(),compensation_order:compensation.into_iter().collect(),omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),contradiction:contradiction.into_iter().collect(),negative_evidence:negative.into_iter().collect(),replay_identity:request.replay_identity.clone(),simulation_digest:d.clone(),effect_receipts:effects,artifact:json!({"artifact_id":format!("worldgen-protocol-simulation:{}",request.protocol_id),"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};r.validate()?;Ok(r)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn req()->ProtocolDraft{let r=h("replay");let s=ProtocolStep{step_id:"step:a".into(),action:"observe".into(),resource_need_milli:200,risk_milli:100,duration_milli:300,compensatable:true,evidence_state:"supported".into(),evidence_digest:h("e"),provenance_digest:h("p"),artifact_digest:h("a"),replay_identity:r.clone(),permitted:true,raw_data_local:true,negative_result:false,boundary:PRECLINICAL_BOUNDARY.into()};ProtocolDraft{request_id:"req:a".into(),protocol_id:"protocol:a".into(),purpose:"preflight".into(),semantic_profile:"preclinical-neural".into(),required_step_order:vec!["step:a".into()],step_order:vec!["step:a".into()],steps:vec![s],replay_identity:r,max_resource_milli:500,max_risk_milli:500,max_duration_milli:500,policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified_protocol(){let r=simulate(&req(),"AFA-worldgen-P10-F01","worldgen-local-protocol-simulation/1.0","local single-study",false).unwrap();assert_eq!(r.disposition,"qualified");assert_eq!(r.admitted_step_order,vec!["step:a"])}#[test]fn unknown_evidence_is_retained(){let mut q=req();q.steps[0].evidence_state="unknown".into();let r=simulate(&q,"AFA-worldgen-P10-F02","worldgen-multimodal-protocol-simulation/1.0","multimodal multi-study",false).unwrap();assert_eq!(r.disposition,"unknown");assert!(!r.uncertainty.is_empty())}}
